use std::collections::HashMap;
fn port(config: &HashMap<&str, &str>) -> Result<u16, String> {
    config.get("port")
        .ok_or_else(|| "port is missing".to_owned())?
        .parse()
        .map_err(|_| "port is not a u16".to_owned())
}
fn main() {
    assert_eq!(port(&HashMap::from([("port", "8080")])), Ok(8080));
}

